public class ManualPlacement {
    public IntPtr Handle;public uint Pid;public DateTime Born;public Native.RECT Bounds;public long Style;public string Path="",GameId="",GameName="",Display="",DisplayKey="";
    public bool Alive(){uint pid;Native.GetWindowThreadProcessId(Handle,out pid);string path;DateTime born;return Native.IsWindow(Handle)&&pid==Pid&&Native.ProcessInfo(pid,out path,out born)&&born==Born;}
}
// Installed only during the explicit pick operation. The selection click is swallowed.
public sealed class WindowClickCapture:IDisposable {
    [StructLayout(LayoutKind.Sequential)] struct MouseData {public Point Point;public uint Data,Flags,Time;public UIntPtr Extra;}
    delegate IntPtr HookProc(int code,IntPtr message,IntPtr data);
    [DllImport("user32.dll",SetLastError=true)] static extern IntPtr SetWindowsHookEx(int kind,HookProc callback,IntPtr module,uint thread);
    [DllImport("user32.dll")] static extern bool UnhookWindowsHookEx(IntPtr hook);
    [DllImport("user32.dll")] static extern IntPtr CallNextHookEx(IntPtr hook,int code,IntPtr message,IntPtr data);
    [DllImport("kernel32.dll",CharSet=CharSet.Auto)] static extern IntPtr GetModuleHandle(string name);
    [DllImport("user32.dll")] static extern IntPtr WindowFromPoint(Point point);
    [DllImport("user32.dll")] static extern IntPtr GetAncestor(IntPtr window,uint flag);
    [DllImport("user32.dll")] static extern short GetAsyncKeyState(int key);
    IntPtr hook,picked;HookProc callback;Control dispatcher;Action<IntPtr> completed;bool finished,down;System.Windows.Forms.Timer timer;DateTime started=DateTime.UtcNow;
    public WindowClickCapture(Control owner,Action<IntPtr> done){dispatcher=owner;completed=done;callback=OnMouse;hook=SetWindowsHookEx(14,callback,GetModuleHandle(null),0);if(hook==IntPtr.Zero)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());timer=new System.Windows.Forms.Timer{Interval=100};timer.Tick+=delegate{if((GetAsyncKeyState(27)&0x8000)!=0||(DateTime.UtcNow-started).TotalSeconds>=30)Finish(IntPtr.Zero);};timer.Start();}
    IntPtr OnMouse(int code,IntPtr message,IntPtr data){if(code>=0&&!finished){int kind=message.ToInt32();if(kind==0x201){down=true;var mouse=(MouseData)Marshal.PtrToStructure(data,typeof(MouseData));picked=GetAncestor(WindowFromPoint(mouse.Point),2);uint ownerPid;Native.GetWindowThreadProcessId(picked,out ownerPid);if(ownerPid==(uint)Process.GetCurrentProcess().Id){picked=IntPtr.Zero;foreach(var window in Native.Windows()){uint pid;Native.GetWindowThreadProcessId(window.Handle,out pid);Native.RECT bounds;if(pid!=(uint)Process.GetCurrentProcess().Id&&Native.GetWindowRect(window.Handle,out bounds)&&Rectangle.FromLTRB(bounds.Left,bounds.Top,bounds.Right,bounds.Bottom).Contains(mouse.Point)){picked=window.Handle;break;}}}return new IntPtr(1);}if(kind==0x202&&down){uint pid;Native.GetWindowThreadProcessId(picked,out pid);var selected=pid==(uint)Process.GetCurrentProcess().Id?IntPtr.Zero:picked;Finish(selected);return new IntPtr(1);}}return CallNextHookEx(hook,code,message,data);}
    void Finish(IntPtr selected){if(finished)return;finished=true;Dispose();if(!dispatcher.IsDisposed)dispatcher.BeginInvoke((Action)delegate{completed(selected);});}
    public void Dispose(){if(hook!=IntPtr.Zero){UnhookWindowsHookEx(hook);hook=IntPtr.Zero;}if(timer!=null){timer.Stop();timer.Dispose();timer=null;}finished=true;}
}
public partial class Launcher {
    HashSet<string> pausedGames=new HashSet<string>();HashSet<string> activeGameIds=new HashSet<string>();
    Dictionary<IntPtr,ManualPlacement> manualHolds=new Dictionary<IntPtr,ManualPlacement>();ManualPlacement lastManual;
    bool SessionPaused(string id){return !String.IsNullOrEmpty(id)&&pausedGames.Contains(id);}
    void UpdateSessionState(WatchResult result){activeGameIds=new HashSet<string>(result.ActiveGameIds);pausedGames.RemoveWhere(id=>!activeGameIds.Contains(id));foreach(var key in manualHolds.Keys.ToArray())if(!manualHolds[key].Alive())manualHolds.Remove(key);}
    void ToggleSessionPause(Game game){if(game==null)return;if(pausedGames.Remove(game.Id)){foreach(var key in states.Keys.Where(k=>states[k].GameId==game.Id).ToArray())states.Remove(key);foreach(var key in manualHolds.Keys.Where(k=>manualHolds[k].GameId==game.Id).ToArray())manualHolds.Remove(key);Say("Automatic movement resumed for "+game.Name);}else{if(!activeGameIds.Contains(game.Id)){MessageBox.Show(this,"Start this game first, then pause its current session.");return;}pausedGames.Add(game.Id);Say(game.Name+" is paused until its detected processes close, or you resume it.");}gameList.Invalidate();}
    ManualPlacement SnapshotWindow(IntPtr window){uint pid;Native.GetWindowThreadProcessId(window,out pid);string path;DateTime born;Native.RECT bounds;if(!Native.IsWindow(window)||!Native.ProcessInfo(pid,out path,out born)||!Native.GetWindowRect(window,out bounds))return null;var game=games.FirstOrDefault(g=>g.Id==(lastCandidates.FirstOrDefault(c=>c.Handle==window)??new Candidate()).GameId)??games.FirstOrDefault(g=>String.Equals(g.Executable,path,StringComparison.OrdinalIgnoreCase))??games.Where(g=>g.MatchFolder&&!String.IsNullOrEmpty(g.Folder)).OrderByDescending(g=>g.Folder.Length).FirstOrDefault(g=>SteamUnlockedLibrary.Within(path,g.Folder));return new ManualPlacement{Handle=window,Pid=pid,Born=born,Path=path,Bounds=bounds,Style=Native.Style(window),GameId=game==null?"":game.Id,GameName=game==null?Path.GetFileNameWithoutExtension(path):game.Name};}
    string MoveManually(IntPtr window,Screen screen){var before=SnapshotWindow(window);if(before==null)return "Cannot read that window. Refresh the list or choose another window.";if(!Native.Move(window,screen,settings.Borderless))return "Windows rejected the move. Try windowed mode in the game.";before.Display=screen.DeviceName;before.DisplayKey=Displays.Key(screen);lastManual=before;manualHolds[window]=before;return "Move requested. Auto-move is held for this window. Use Remember monitor, Undo, or select another window.";}
    string UndoManualMove(){if(lastManual==null||!lastManual.Alive())return "The last moved window has closed or changed; nothing was restored.";var item=lastManual;Native.Style(item.Handle,item.Style);var r=item.Bounds;if(!Native.SetWindowPos(item.Handle,IntPtr.Zero,r.Left,r.Top,r.Right-r.Left,r.Bottom-r.Top,0x0004|0x0010|0x0020|0x4000))return "Windows rejected the undo request.";manualHolds[item.Handle]=item;lastManual=null;return "Original position and size requested. Auto-move stays held for this window until it closes or you resume it.";}
    void RememberManualMonitor(){if(lastManual==null||!lastManual.Alive()){MessageBox.Show(this,"Move a running window first.");return;}var item=lastManual;CustomGame added=null;string id=item.GameId;
        if(String.IsNullOrEmpty(id)){if(!File.Exists(item.Path)||!item.Path.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)){MessageBox.Show(this,"This window does not expose a game EXE. Add the game manually first.");return;}if(MessageBox.Show(this,"Add "+item.GameName+" as a custom game and remember this monitor?","Remember monitor",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;added=new CustomGame{Id="custom:"+Guid.NewGuid().ToString("N"),Name=item.GameName,Executable=item.Path};settings.CustomGames.Add(added);id=added.Id;}
        var old=settings.Profiles.FirstOrDefault(p=>p.Id==id);var profile=new Profile{Id=id,Override=true,Monitor=item.Display,MonitorKey=item.DisplayKey,Borderless=old==null?settings.Borderless:old.Borderless,UseLayout=old!=null&&old.UseLayout,X=old==null?0:old.X,Y=old==null?0:old.Y,Width=old==null?0:old.Width,Height=old==null?0:old.Height};if(old!=null)settings.Profiles.Remove(old);settings.Profiles.Add(profile);
        if(!Save()){settings.Profiles.Remove(profile);if(old!=null)settings.Profiles.Add(old);if(added!=null)settings.CustomGames.Remove(added);return;}manualHolds.Remove(item.Handle);item.GameId=id;CatalogChanged();Say("Saved "+item.Display+" as the default monitor for "+item.GameName+".");
    }
    void MonitorPresets(){using(var form=ToolForm("Monitor presets")){var body=ToolStack(form);body.Controls.Add(new Label{Text="Save your current global target, borderless setting and fallback as Desk, TV or Streaming. Per-game overrides remain active; edit them in Game settings if needed.",Width=610,Height=80});var list=new ListBox{Width=610,Height=180,BackColor=Theme.Raised,ForeColor=Theme.Text};body.Controls.Add(list);Action reload=delegate{list.Items.Clear();foreach(var p in settings.MonitorPresets)list.Items.Add(p);if(list.Items.Count>0)list.SelectedIndex=0;};var name=new TextBox{Width=610};body.Controls.Add(new Label{Text="Preset name",AutoSize=true});body.Controls.Add(name);
        ToolButton(body,"Save current display settings",delegate{string title=name.Text.Trim();if(title.Length==0||title.Length>60){MessageBox.Show(form,"Enter a name between 1 and 60 characters.");return;}var old=settings.MonitorPresets.FirstOrDefault(p=>String.Equals(p.Name,title,StringComparison.OrdinalIgnoreCase));if(old!=null&&MessageBox.Show(form,"Replace preset "+old.Name+"?","Replace preset",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var preset=new MonitorPreset{Name=title,Monitor=settings.Monitor,MonitorKey=settings.MonitorKey,Borderless=settings.Borderless,FallbackEnabled=settings.FallbackEnabled,FallbackKey=settings.FallbackKey};if(old!=null)settings.MonitorPresets.Remove(old);settings.MonitorPresets.Add(preset);if(!Save()){settings.MonitorPresets.Remove(preset);if(old!=null)settings.MonitorPresets.Add(old);return;}reload();});
        ToolButton(body,"Apply selected preset",delegate{var p=list.SelectedItem as MonitorPreset;if(p==null)return;var old=new MonitorPreset{Monitor=settings.Monitor,MonitorKey=settings.MonitorKey,Borderless=settings.Borderless,FallbackEnabled=settings.FallbackEnabled,FallbackKey=settings.FallbackKey};ApplyPreset(p);if(!Save()){ApplyPreset(old);return;}loading=true;border.Checked=settings.Borderless;loading=false;states.Clear();LoadDisplays();Say("Applied preset "+p.Name+". Per-game overrides remain active.");});
        ToolButton(body,"Delete selected preset",delegate{var p=list.SelectedItem as MonitorPreset;if(p==null)return;settings.MonitorPresets.Remove(p);if(!Save()){settings.MonitorPresets.Add(p);return;}reload();});reload();form.ShowDialog(this);
    }}
    void ApplyPreset(MonitorPreset p){settings.Monitor=p.Monitor;settings.MonitorKey=p.MonitorKey;settings.Borderless=p.Borderless;settings.FallbackEnabled=p.FallbackEnabled;settings.FallbackKey=p.FallbackKey;}
    internal void SessionFeatureChecks(){
        pausedGames.Add("fixture");UpdateSessionState(new WatchResult{ActiveGameIds=new List<string>{"fixture"}});if(!SessionPaused("fixture"))throw new InvalidDataException("Session pause was lost while game remained running");UpdateSessionState(new WatchResult());if(SessionPaused("fixture"))throw new InvalidDataException("Session pause remained after game exit");
        var preset=new MonitorPreset{Name="Fixture",Monitor="test",MonitorKey="test-key",Borderless=true,FallbackEnabled=true,FallbackKey="fallback"};var old=new MonitorPreset{Monitor=settings.Monitor,MonitorKey=settings.MonitorKey,Borderless=settings.Borderless,FallbackEnabled=settings.FallbackEnabled,FallbackKey=settings.FallbackKey};ApplyPreset(preset);if(settings.MonitorKey!="test-key"||!settings.Borderless||!settings.FallbackEnabled)throw new InvalidDataException("Preset application failed");ApplyPreset(old);
        using(var fixture=new Form{Text="Launcher placement fixture",StartPosition=FormStartPosition.Manual,Bounds=new Rectangle(40,40,360,240)}){
            fixture.Show();Application.DoEvents();var before=SnapshotWindow(fixture.Handle);if(before==null||!before.Alive())throw new InvalidDataException("Window identity snapshot failed");lastManual=before;fixture.Location=new Point(120,120);Application.DoEvents();UndoManualMove();Application.DoEvents();System.Threading.Thread.Sleep(100);Native.RECT actual;Native.GetWindowRect(fixture.Handle,out actual);if(Math.Abs(actual.Left-before.Bounds.Left)>4||Math.Abs(actual.Top-before.Bounds.Top)>4)throw new InvalidDataException("Manual undo failed on fixture window");fixture.Close();if(before.Alive())throw new InvalidDataException("Closed window accepted for undo");manualHolds.Clear();lastManual=null;
        }
        using(var picker=CreateWindowPicker()){picker.Show();Application.DoEvents();using(var preview=new Bitmap(picker.Width,picker.Height)){picker.DrawToBitmap(preview,new Rectangle(Point.Empty,picker.Size));preview.Save(Path.Combine(Diagnostics.Folder,"window-picker-preview.png"));}picker.Close();}
    }
    void SetupWizard(){using(var form=ToolForm("Set up Steam Monitor")){var body=ToolStack(form);body.Controls.Add(new Label{Text="1. Choose the display for your games",Width=610,Height=35});var display=new ComboBox{Width=610,DropDownStyle=ComboBoxStyle.DropDownList};foreach(var d in Displays.All())display.Items.Add(d);var current=Displays.Resolve(settings.MonitorKey,settings.Monitor);for(int i=0;i<display.Items.Count;i++)if(current!=null&&((DisplayIdentity)display.Items[i]).Key==current.Key)display.SelectedIndex=i;body.Controls.Add(display);
        ToolButton(body,"2. Test this display",delegate{var selected=display.SelectedItem as DisplayIdentity;if(selected==null){MessageBox.Show(form,"Choose a display first.");return;}ShowDisplayTest(selected);});
        var start=new CheckBox{Text="3. Start in the background when I sign in",AutoSize=true,Checked=StartupEnabled()};body.Controls.Add(start);var automatic=new CheckBox{Text="Automatically move detected games",AutoSize=true,Checked=settings.Enabled};body.Controls.Add(automatic);body.Controls.Add(new Label{Text="Launch games normally. Closing the main window keeps this app in the tray. Some games need Windowed or Borderless mode in their own video settings.",Width=610,Height=90});
        ToolButton(body,"Finish setup",delegate{var selected=display.SelectedItem as DisplayIdentity;if(selected==null){MessageBox.Show(form,"Choose a display first.");return;}if(!SetStartup(start.Checked))return;string oldMonitor=settings.Monitor,oldKey=settings.MonitorKey;bool oldEnabled=settings.Enabled,oldComplete=settings.SetupCompleted;settings.Monitor=selected.Screen.DeviceName;settings.MonitorKey=selected.Key;settings.Enabled=automatic.Checked;settings.SetupCompleted=true;if(!Save()){settings.Monitor=oldMonitor;settings.MonitorKey=oldKey;settings.Enabled=oldEnabled;settings.SetupCompleted=oldComplete;return;}loading=true;enabled.Checked=settings.Enabled;loading=false;LoadDisplays();states.Clear();Status();form.Close();});form.ShowDialog(this);
    }}
}
